"use strict";
// Precomputes what parsing the default stylesheet (src/jsdom/browser/default-stylesheet.css) derives from its text
// alone, so that the first getComputedStyle() of a process doesn't have to: the declaration blocks of its style rules,
// as validated by the property parsers. See getDefaultStyleSheet() in
// src/jsdom/living/css/helpers/default-stylesheet.js.
//
// The output, src/jsdom/browser/default-stylesheet-data.json, is committed rather than generated by `npm run prepare`:
// generating it runs jsdom, which needs the Rust core, and `npm ci` runs prepare before the core is built (and the
// release job publishes without building it). Run this script after changing the default stylesheet, or the parsing
// or serialization of the properties it uses; tests/api/css-startup.js fails until then. The data is only a cache: it
// is only used when the stylesheet's hash matches.
const fs = require("node:fs");
const path = require("node:path");
const { JSDOM } = require("../src/api.js");
const cssParser = require("../src/jsdom/living/css/helpers/css-parser.js");
const { hashDefaultStyleSheet } = require("../src/jsdom/living/css/helpers/default-stylesheet.js");

const sourcePath = path.resolve(__dirname, "../src/jsdom/browser/default-stylesheet.css");
const dest = path.resolve(__dirname, "../src/jsdom/browser/default-stylesheet-data.json");

const cssText = fs.readFileSync(sourcePath, { encoding: "utf-8" });
const { window } = new JSDOM();
cssParser.parseStyleSheet(cssText, window);
const declarationBlocks = cssParser.getDeclarationBlockSnapshots(cssText);
window.close();

// One declaration block per line, for readable diffs.
const output = `{
  "hash": ${JSON.stringify(hashDefaultStyleSheet(cssText))},
  "declarationBlocks": [
${declarationBlocks.map(entry => `    ${JSON.stringify(entry)}`).join(",\n")}
  ]
}
`;

fs.writeFileSync(dest, output);
